pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, uint unlockTime, uint putAmount1, uint putAmount2, uint collectAmount) public {
        // Bound inputs to realistic ranges
        vm.assume(sender != address(0) && sender != address(this));
        vm.assume(putAmount1 >= 1 && putAmount1 <= 100 ether);
        vm.assume(putAmount2 >= 1 && putAmount2 <= 100 ether);
        vm.assume(collectAmount >= 1 && collectAmount <= 100 ether);
        vm.assume(unlockTime >= block.timestamp && unlockTime <= block.timestamp + 365 days);

        // Fund the test contract to send ether
        vm.deal(address(this), putAmount1 + putAmount2 + collectAmount);

        // First Put
        vm.prank(sender);
        c.Put{value: putAmount1}(unlockTime);

        // Second Put
        vm.prank(sender);
        c.Put{value: putAmount2}(unlockTime);

        // Fast forward to unlock time
        vm.warp(unlockTime + 1);

        // Get initial balance of sender
        uint senderBalanceBefore = address(sender).balance;

        // Try Collect - ensure the account has enough balance
        uint accBalance = c.Acc(sender).balance;
        if (accBalance >= c.MinSum() && accBalance >= collectAmount) {
            vm.prank(sender);
            c.Collect(collectAmount);
        }

        // Check the invariant: after the Collect, the sum of all Puts minus the collected amount should equal the stored balance
        // If collect didn't happen (due to insufficient balance), the stored balance should equal sum of puts
        uint storedBalance = c.Acc(sender).balance;
        uint expectedBalance;
        if (accBalance >= c.MinSum() && accBalance >= collectAmount) {
            expectedBalance = putAmount1 + putAmount2 - collectAmount;
        } else {
            expectedBalance = putAmount1 + putAmount2;
        }

        assertTrue(storedBalance == expectedBalance, "Balance invariant violated");
    }
}

