pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 unlockTime, uint256 totalDeposit, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        vm.assume(user != address(0));
        vm.assume(user != address(c));
        unlockTime = bound(unlockTime, 0, type(uint256).max);
        totalDeposit = bound(totalDeposit, 1 ether, 1000 ether);
        collectAmount = bound(collectAmount, 1 ether, totalDeposit);

        // Give the user Ether
        vm.deal(user, totalDeposit);

        // User deposits
        vm.startPrank(user);
        c.Put{value: totalDeposit}(unlockTime);
        vm.stopPrank();

        // Warp past unlock time
        vm.warp(block.timestamp + unlockTime + 1);

        // Record contract balance before collect
        uint256 balanceBefore = address(c).balance;

        // User attempts to collect
        vm.startPrank(user);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        vm.stopPrank();

        // Only check if the call succeeded (otherwise no state change)
        if (success) {
            uint256 balanceAfter = address(c).balance;
            // General rule: contract balance must decrease by at most _am (could be less due to rounding/gas but never increase)
            assertTrue(balanceAfter <= balanceBefore, "Contract balance should not increase after Collect");
            assertTrue(balanceAfter >= balanceBefore - collectAmount, "Contract balance should not decrease by more than collected amount");
        }
    }
}

