    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am) public {
        vm.assume(am <= type(uint256).max - 1 ether);
        // Make a deposit so balance is sufficient for collect
        c.Put{value: 2 ether}(block.timestamp - 1);
        // Try to collect; it may revert if conditions not met, but MinSum should be unchanged
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));
        // Regardless of success, MinSum must be >= 1 ether
        assertTrue(c.MinSum() >= 1 ether);
    }
}

