pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 initDeposit, uint256 withdrawAmount) public {
        vm.assume(user != address(0));
        vm.assume(initDeposit > 0);
        vm.assume(withdrawAmount <= initDeposit);
        vm.assume(withdrawAmount >= 1 ether); // ensure MinSum condition is relevant

        // Fund user and deposit
        vm.deal(user, initDeposit);
        vm.prank(user);
        c.Put{value: initDeposit}(block.timestamp + 1);

        // Record balance before Collect
        uint256 balanceBefore = address(c).balance;

        // Attempt Collect
        vm.prank(user);
        c.Collect(withdrawAmount);

        // Check balance decreased by exactly withdrawAmount if Collect succeeded
        uint256 balanceAfter = address(c).balance;
        // The rule: balance should decrease by withdrawAmount (if Collect didn't revert)
        // But we only assert it didn't revert? Actually we want a general rule that holds for reference.
        // For reference: if collect succeeds, balance decreases by withdrawAmount.
        // For mutant: MinSum=0 makes condition true always, but collect may still succeed.
        // Actually the mutant has MinSum=0, so the condition acc.balance>=MinSum is always true.
        // But the reference requires MinSum>=1 ether, so collect only happens if acc.balance >= 1 ether.
        // So a general rule: whenever Collect does NOT revert, the balance decreases by withdrawAmount.
        // But we need a rule that holds for all inputs on reference.
        // Better: The balance change is either 0 (if collect reverted) or -withdrawAmount.
        // That's hard to express as true/false. Let's try a different approach:
        // The difference is: reference's MinSum is 1 ether, mutant's is 0.
        // So a rule that holds on reference but fails on mutant could be:
        // "If deposit < 1 ether, Collect will always revert"
        // But we can test: for small deposits, reference reverts, mutant may succeed.
        vm.assume(initDeposit < 1 ether);
        vm.deal(user, initDeposit);
        vm.prank(user);
        c.Put{value: initDeposit}(block.timestamp + 1);

        vm.assume(withdrawAmount <= initDeposit);
        vm.prank(user);
        // We want to see if Collect reverts
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdrawAmount));
        assertTrue(success == false, "Collect should revert when deposit < 1 ether");
    }
}

