pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address account, uint256 amount) public {
        vm.assume(account != address(this));
        vm.assume(account != address(0));
        vm.prank(account);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Put(uint256)", block.timestamp + 1));
        require(success);
        vm.warp(block.timestamp + 2);
        vm.prank(account);
        (bool reverted, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));
        assertTrue(reverted, "Collect should revert when caller has zero balance");
    }
}
